// MIT first-party bounded offline ClrMD queries. No attachment or expression evaluation.
using Microsoft.Diagnostics.Runtime;
using System.Collections.Immutable;
using System.Runtime.InteropServices;
using System.Text.Json;
using System.Text.Json.Serialization;
sealed class Plan {public int Schema{get;set;}public string Input{get;set;}="";public string Dac{get;set;}="";public string View{get;set;}="overview";public string? Type{get;set;}public string? Address{get;set;}public uint? Thread{get;set;}public int Runtime{get;set;}public int Limit{get;set;}=50;public int Offset{get;set;}public int MaxObjects{get;set;}=1000000;}
sealed class NoFiles:IFileLocator {public string? FindPEImage(string f,int t,int s,bool c)=>null;public string? FindPEImage(string f,SymbolProperties p,ImmutableArray<byte>b,OSPlatform o,bool c)=>null;}
static class Program {
 static readonly JsonSerializerOptions Json=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,DefaultIgnoreCondition=JsonIgnoreCondition.WhenWritingNull};
 static string Address(ulong address)=>"0x"+address.ToString("x");
 static object Field(ClrObject obj,ClrInstanceField field){try{object? value=field.ElementType switch{ClrElementType.Boolean=>obj.ReadField<bool>(field),ClrElementType.Char=>obj.ReadField<char>(field).ToString(),ClrElementType.Int8=>obj.ReadField<sbyte>(field),ClrElementType.UInt8=>obj.ReadField<byte>(field),ClrElementType.Int16=>obj.ReadField<short>(field),ClrElementType.UInt16=>obj.ReadField<ushort>(field),ClrElementType.Int32=>obj.ReadField<int>(field),ClrElementType.UInt32=>obj.ReadField<uint>(field),ClrElementType.Int64=>obj.ReadField<long>(field).ToString(System.Globalization.CultureInfo.InvariantCulture),ClrElementType.UInt64=>obj.ReadField<ulong>(field).ToString(System.Globalization.CultureInfo.InvariantCulture),ClrElementType.Float=>obj.ReadField<float>(field).ToString(System.Globalization.CultureInfo.InvariantCulture),ClrElementType.Double=>obj.ReadField<double>(field).ToString(System.Globalization.CultureInfo.InvariantCulture),ClrElementType.String=>obj.ReadStringField(field,257),_=>field.IsObjectReference?Address(obj.ReadObjectField(field).Address):null};bool truncated=value is string str&&field.ElementType==ClrElementType.String&&str.Length>256;if(truncated)value=((string)value!)[..256];return new{name=field.Name,type=field.Type?.Name,kind=field.ElementType.ToString(),value,available=value is not null,truncated};}catch(Exception error){return new{name=field.Name,type=field.Type?.Name,kind=field.ElementType.ToString(),available=false,error=error.Message};}}
 static object Query(Plan p){using var target=DataTarget.LoadDump(p.Input,new DataTargetOptions{FileLocator=new NoFiles(),SymbolPaths=[]});if(p.Runtime<0||p.Runtime>=target.ClrVersions.Length)throw new InvalidOperationException("No selected CLR runtime in this dump");var info=target.ClrVersions[p.Runtime];using var runtime=info.CreateRuntime(p.Dac,false);var heap=runtime.Heap;object observation;bool complete=true;string? reason=null;
 if(p.View=="overview"){observation=new{architecture=target.DataReader.Architecture.ToString(),pointerSize=target.DataReader.PointerSize,runtime=info.Version.ToString(),flavor=info.Flavor.ToString(),runtimeIndex=p.Runtime,availableRuntimes=target.ClrVersions.Select((c,n)=>new{index=n,version=c.Version.ToString(),flavor=c.Flavor.ToString()}).ToArray(),canWalkHeap=heap.CanWalkHeap,threads=runtime.Threads.Length};}
 else if(p.View=="objects"){if(!heap.CanWalkHeap)throw new InvalidOperationException("Heap cannot be walked in this dump; capture a compatible Heap or Full dump");var items=new List<object>();int scanned=0,matching=0;foreach(var obj in heap.EnumerateObjects()){if(scanned>=p.MaxObjects){complete=false;reason="object_scan_bound";break;}scanned++;if(obj.IsFree||!obj.IsValid||p.Type is not null&&obj.Type?.Name!=p.Type)continue;if(matching>=p.Offset&&items.Count<p.Limit)items.Add(new{address=Address(obj.Address),type=obj.Type?.Name,size=obj.Size.ToString()});matching++;}observation=new{items,scannedObjects=scanned,matchingInScannedPrefix=matching,limit=p.Limit,offset=p.Offset,truncated=p.Offset+p.Limit<matching,maxObjects=p.MaxObjects};}
 else if(p.View=="object"){var obj=heap.GetObject(Convert.ToUInt64(p.Address![2..],16));if(!obj.IsValid||obj.IsFree||obj.Type is null)throw new InvalidOperationException("Address is not a readable managed object in this exact dump");if(p.Type is not null&&p.Type!=obj.Type.Name)throw new InvalidOperationException("Object type differs from the explicit expected type");observation=new{address=Address(obj.Address),type=obj.Type.Name,size=obj.Size.ToString(),fields=obj.Type.Fields.Skip(p.Offset).Take(p.Limit).Select(f=>Field(obj,f)).ToArray(),totalFields=obj.Type.Fields.Length,limit=p.Limit,offset=p.Offset,truncated=p.Offset+p.Limit<obj.Type.Fields.Length};}
 else if(p.View=="stacks"){var threads=runtime.Threads.Where(t=>!p.Thread.HasValue||t.OSThreadId==p.Thread).ToArray();var rows=threads.Skip(p.Offset).Take(p.Limit).Select(t=>{var frames=t.EnumerateStackTrace(false,129).ToArray();if(frames.Length>128){complete=false;reason="stack_frame_bound";}return new{osThreadId=t.OSThreadId,managedThreadId=t.ManagedThreadId,isAlive=t.IsAlive,frames=frames.Take(128).Select(s=>new{instructionPointer=Address(s.InstructionPointer),stackPointer=Address(s.StackPointer),method=s.Method?.Signature,kind=s.Kind.ToString()}).ToArray(),truncated=frames.Length>128};}).ToArray();if(p.Thread.HasValue&&threads.Length==0)throw new InvalidOperationException("Selected OS thread was not found");observation=new{items=rows,total=threads.Length,limit=p.Limit,offset=p.Offset,truncated=p.Offset+p.Limit<threads.Length};}
 else throw new InvalidOperationException("Unknown offline dump view");return new{state=complete?"completed":"partial",complete,reason,view=p.View,observation,scope="One immutable dump and explicitly selected matching native DAC. No live attachment, automatic file/symbol download or expression evaluation. Unreadable fields remain unknown; addresses belong only to this dump. A bounded prefix cannot establish global absence."};}
 public static int Main(string[] args){try{if(args.Length!=1||!Path.IsPathFullyQualified(args[0])||new FileInfo(args[0]).Length>16384)throw new InvalidOperationException("A bounded absolute private plan is required");var p=JsonSerializer.Deserialize<Plan>(File.ReadAllText(args[0]),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??throw new InvalidOperationException("Missing plan");if(p.Schema!=1||!Path.IsPathFullyQualified(p.Input)||!Path.IsPathFullyQualified(p.Dac)||p.Limit<1||p.Limit>500||p.Offset<0||p.MaxObjects<1||p.MaxObjects>1000000)throw new InvalidOperationException("Invalid dump query bounds");Console.WriteLine(JsonSerializer.Serialize(Query(p),Json));return 0;}catch(Exception error){Console.WriteLine(JsonSerializer.Serialize(new{state="failed",error=error.Message.Length>4096?error.Message[..4096]:error.Message},Json));return 70;}}
}
